//! # Win32 API Öykünme Katmanı
//!
//! Windows uygulamalarını echOS üzerinde çalıştırmak için Win32 API öykünmesi.
//! `kernel32`, `user32` ve `gdi32` gibi yaygın Win32 API'lerini uygular.

use alloc::boxed::Box;
use alloc::collections::BTreeMap;
use alloc::string::String;
use alloc::string::ToString;
use alloc::vec;
use alloc::vec::Vec;
use core::arch::asm;
use core::sync::atomic::{AtomicU32, Ordering};
use spin::{Mutex, Once};

// ============================================================================
// WIN32 TYPES
// ============================================================================

pub type HANDLE = u64;
pub type HMODULE = u64;
pub type HWND = u64;
pub type HDC = u64;
pub type HINSTANCE = u64;
pub type HMENU = u64;
pub type HICON = u64;
pub type HCURSOR = u64;
pub type HBRUSH = u64;
pub type HFONT = u64;
pub type HBITMAP = u64;
pub type HGDIOBJ = u64;
pub type HPEN = u64;
pub type HPALETTE = u64;
pub type HRGN = u64;
pub type HACCEL = u64;
pub type HMETAFILE = u64;
pub type HENHMETAFILE = u64;
pub type HKEY = u64;
pub type SC_HANDLE = u64;
pub type HCRYPTPROV = u64;
pub type HCRYPTKEY = u64;
pub type HCRYPTHASH = u64;
pub type HDROP = u64;
pub type HRESULT = i32;
pub type DWORD_PTR = u64;
pub type BSTR = *mut u16;

#[repr(C)]
#[derive(Clone, Copy, Debug, Default)]
pub struct IoRingBufferDescriptor {
    pub address: u64,
    pub length: u32,
    pub reserved: u32,
}

#[repr(C)]
#[derive(Clone, Copy, Debug, Default)]
pub struct IoRingCompletionEntry {
    pub user_data: u64,
    pub result_code: i32,
    pub information: u32,
    pub operation: u32,
}

pub type LPSTR = *mut i8;
pub type LPCSTR = *const i8;
pub type LPWSTR = *mut u16;
pub type LPCWSTR = *const u16;
pub type LPVOID = *mut u8;
pub type LPCVOID = *const u8;

pub type DWORD = u32;
pub type WORD = u16;
pub type BYTE = u8;
pub type BOOL = i32;
pub type UINT = u32;
pub type INT = i32;
pub type LONG = i32;
pub type ULONG = u32;
pub type SIZE_T = u64;
pub type SHORT = i16;
pub type ULONG_PTR = u64;
pub type LCID = DWORD;
pub type DISPID = LONG;

pub type FARPROC = Option<unsafe extern "system" fn() -> isize>;
pub type PROC = Option<unsafe extern "system" fn() -> isize>;
pub type LPTOP_LEVEL_EXCEPTION_FILTER =
    Option<unsafe extern "system" fn(*mut EXCEPTION_POINTERS) -> LONG>;

