struct ReportedPointerSnapshot {
    x: INT,
    y: INT,
    buttons: crate::drivers::mouse::MouseButtons,
    swap_buttons: bool,
}

#[repr(C, align(64))]
struct ReportedPointerPublicationState {
    sequence: core::sync::atomic::AtomicU64,
    x: core::sync::atomic::AtomicI32,
    y: core::sync::atomic::AtomicI32,
    buttons: core::sync::atomic::AtomicU8,
    swap_buttons: core::sync::atomic::AtomicBool,
}

impl ReportedPointerPublicationState {
    const fn new() -> Self {
        Self {
            sequence: core::sync::atomic::AtomicU64::new(0),
            x: core::sync::atomic::AtomicI32::new(0),
            y: core::sync::atomic::AtomicI32::new(0),
            buttons: core::sync::atomic::AtomicU8::new(0),
            swap_buttons: core::sync::atomic::AtomicBool::new(false),
        }
    }

    fn begin_write(&self) -> u64 {
        loop {
            let sequence = self.sequence.load(core::sync::atomic::Ordering::Relaxed);
            if (sequence & 1) != 0 {
                core::hint::spin_loop();
                continue;
            }
            if self
                .sequence
                .compare_exchange_weak(
                    sequence,
                    sequence + 1,
                    core::sync::atomic::Ordering::Acquire,
                    core::sync::atomic::Ordering::Relaxed,
                )
                .is_ok()
            {
                return sequence + 2;
            }
            core::hint::spin_loop();
        }
    }

    fn finish_write(&self, published_sequence: u64) {
        self.sequence
            .store(published_sequence, core::sync::atomic::Ordering::Release);
    }

    fn snapshot(&self) -> ReportedPointerSnapshot {
        loop {
            let sequence = self.sequence.load(core::sync::atomic::Ordering::Acquire);
            if (sequence & 1) != 0 {
                core::hint::spin_loop();
                continue;
            }
            let snapshot = ReportedPointerSnapshot {
                x: self.x.load(core::sync::atomic::Ordering::Relaxed),
                y: self.y.load(core::sync::atomic::Ordering::Relaxed),
                buttons: decode_mouse_button_bits(
                    self.buttons.load(core::sync::atomic::Ordering::Relaxed),
                ),
                swap_buttons: self
                    .swap_buttons
                    .load(core::sync::atomic::Ordering::Relaxed),
            };
            let end_sequence = self.sequence.load(core::sync::atomic::Ordering::Acquire);
            if sequence == end_sequence {
                return snapshot;
            }
            core::hint::spin_loop();
        }
    }

    fn update<F: FnOnce(&mut ReportedPointerSnapshot)>(&self, mutate: F) {
        let published_sequence = self.begin_write();
        let mut snapshot = ReportedPointerSnapshot {
            x: self.x.load(core::sync::atomic::Ordering::Relaxed),
            y: self.y.load(core::sync::atomic::Ordering::Relaxed),
            buttons: decode_mouse_button_bits(
                self.buttons.load(core::sync::atomic::Ordering::Relaxed),
            ),
            swap_buttons: self
                .swap_buttons
                .load(core::sync::atomic::Ordering::Relaxed),
        };
        mutate(&mut snapshot);
        self.x
            .store(snapshot.x, core::sync::atomic::Ordering::Relaxed);
        self.y
            .store(snapshot.y, core::sync::atomic::Ordering::Relaxed);
        self.buttons.store(
            encode_mouse_button_bits(snapshot.buttons),
            core::sync::atomic::Ordering::Relaxed,
        );
        self.swap_buttons
            .store(snapshot.swap_buttons, core::sync::atomic::Ordering::Relaxed);
        self.finish_write(published_sequence);
    }
}

static REPORTED_POINTER_PUBLICATION_STATE: ReportedPointerPublicationState =
    ReportedPointerPublicationState::new();

/// Mesaj kuyruğuna mesaj ekle
pub fn post_message(hwnd: u64, message: u32, wparam: u64, lparam: i64) -> bool {
    post_message_with_point(hwnd, message, wparam, lparam, 0, 0)
}

pub fn post_message_with_point(
    hwnd: u64,
    message: u32,
    wparam: u64,
    lparam: i64,
    pt_x: i32,
    pt_y: i32,
) -> bool {
    MSG_QUEUE.lock().push(Win32Msg {
        hwnd,
        message,
        wparam,
        lparam,
        time: get_tick_count_internal(),
        pt_x,
        pt_y,
    });
    true
}

/// Mesaj kuyruğundan mesaj al (blocking değil)
pub fn peek_message(hwnd_filter: u64) -> Option<Win32Msg> {
    let mut queue = MSG_QUEUE.lock();
    if hwnd_filter == 0 {
        // Herhangi bir pencere için
        if !queue.is_empty() {
            return Some(queue.remove(0));
        }
    } else {
        // Belirli pencere için
        if let Some(idx) = queue
            .iter()
            .position(|m| m.hwnd == hwnd_filter || m.hwnd == 0)
        {
            return Some(queue.remove(idx));
        }
    }
    None
}

/// TSC tabanlı tick sayacı (ms)
fn get_tick_count_internal() -> u32 {
    let low: u32;
    let high: u32;
    unsafe {
        core::arch::asm!(
            "rdtsc",
            out("eax") low,
            out("edx") high,
            options(nomem, nostack, preserves_flags)
        );
    }
    let tsc = ((high as u64) << 32) | (low as u64);
    // Yaklaşık 3GHz CPU varsayımı → /3_000_000 ≈ ms
    (tsc / 3_000_000) as u32
}

/// Pencere surface'ını framebuffer'a kopyala
pub fn blit_window_to_framebuffer(hwnd: u64) {
    let windows = WIN32_WINDOWS.lock();
    if let Some(win) = windows.get(&hwnd) {
        if !win.visible || win.surface.is_empty() {
            return;
        }

        // Framebuffer'a doğrudan blit
        if let Some(mut fb) = crate::boot::get_global_framebuffer() {
            let fb_width = fb.width as i32;
            let fb_height = fb.height as i32;
            let (client_x, client_y) = window_client_origin(win);

            for y in 0..win.height {
                let dst_y = client_y + y;
                if dst_y < 0 || dst_y >= fb_height {
                    continue;
                }

                for x in 0..win.width {
                    let dst_x = client_x + x;
                    if dst_x < 0 || dst_x >= fb_width {
                        continue;
                    }

                    let src_idx = ((y * win.width + x) * 4) as usize;
                    if src_idx + 3 >= win.surface.len() {
                        continue;
                    }

                    let b = win.surface[src_idx];
                    let g = win.surface[src_idx + 1];
                    let r = win.surface[src_idx + 2];
                    let a = win.surface[src_idx + 3];

                    if a == 0 {
                        continue;
                    } // Tamamen saydam

                    // ARGB format (0xAARRGGBB)
                    let color =
                        ((a as u32) << 24) | ((r as u32) << 16) | ((g as u32) << 8) | (b as u32);

                    if a == 255 {
                        // Opak — doğrudan çiz
                        fb.plot_pixel(dst_x as usize, dst_y as usize, color);
                    } else {
                        // Alpha blend
                        let existing = fb.get_pixel(dst_x as usize, dst_y as usize);
                        let dst_r = ((existing >> 16) & 0xFF) as u32;
                        let dst_g = ((existing >> 8) & 0xFF) as u32;
                        let dst_b = (existing & 0xFF) as u32;
                        let alpha = a as u32;
                        let inv_alpha = 255 - alpha;
                        let new_r = (r as u32 * alpha + dst_r * inv_alpha) / 255;
                        let new_g = (g as u32 * alpha + dst_g * inv_alpha) / 255;
                        let new_b = (b as u32 * alpha + dst_b * inv_alpha) / 255;
                        let blended = 0xFF000000 | (new_r << 16) | (new_g << 8) | new_b;
                        fb.plot_pixel(dst_x as usize, dst_y as usize, blended);
                    }
                }
            }
            draw_window_non_client_to_fb(&mut fb, win);
        }
    }
}

// ============================================================================
// DLL HANDLE TABLE — maps HMODULE → normalised module name (lowercase, no .dll)
// ============================================================================

static DLL_HANDLES: Mutex<BTreeMap<u64, String>> = Mutex::new(BTreeMap::new());

/// Well-known baseline handle values for the modules we emulate.
const HMOD_KERNEL32: u64 = 0x0010_0000;
const HMOD_USER32: u64 = 0x0010_1000;
const HMOD_GDI32: u64 = 0x0010_2000;
const HMOD_ADVAPI32: u64 = 0x0010_3000;
const HMOD_MSVCRT: u64 = 0x0010_4000;
const HMOD_SHELL32: u64 = 0x0010_5000;
const HMOD_NTDLL: u64 = 0x0010_6000;
const HMOD_WS2_32: u64 = 0x0010_7000;
const HMOD_WINHTTP: u64 = 0x0010_8000;
const HMOD_WININET: u64 = 0x0010_9000;
const HMOD_OLE32: u64 = 0x0010_A000;
const HMOD_OLEAUT32: u64 = 0x0010_B000;

/// Initialise the well-known DLL handles (called once at Win32 init).
pub fn init_dll_handles() {
    let mut map = DLL_HANDLES.lock();
    map.insert(HMOD_KERNEL32, "kernel32".into());
    map.insert(HMOD_USER32, "user32".into());
    map.insert(HMOD_GDI32, "gdi32".into());
    map.insert(HMOD_ADVAPI32, "advapi32".into());
    map.insert(HMOD_MSVCRT, "msvcrt".into());
    map.insert(HMOD_SHELL32, "shell32".into());
    map.insert(HMOD_NTDLL, "ntdll".into());
    map.insert(HMOD_WS2_32, "ws2_32".into());
    map.insert(HMOD_WINHTTP, "winhttp".into());
    map.insert(HMOD_WININET, "wininet".into());
    map.insert(HMOD_OLE32, "ole32".into());
    map.insert(HMOD_OLEAUT32, "oleaut32".into());
}

/// Resolve a module name to a canonical handle and register it if not present.
pub fn handle_for_module(name: &str) -> u64 {
    let key = name.to_lowercase();
    let key = key.trim_end_matches(".dll");
    // Check existing handles
    {
        let map = DLL_HANDLES.lock();
        for (&h, n) in map.iter() {
            if n == key {
                return h;
            }
        }
    }
    // Assign a new handle: use a simple counter above our static range
    let h = next_dll_module_handle();
    DLL_HANDLES.lock().insert(h, key.to_string());
    h
}

/// Reverse lookup: handle → module name string.
pub fn module_for_handle(hmod: u64) -> Option<String> {
    DLL_HANDLES.lock().get(&hmod).cloned()
}

