fn current_win32_process_key() -> u64 {
    crate::pe_loader::current_process_pid().unwrap_or_else(current_win32_thread_key)
}

fn current_win32_teb() -> Option<&'static mut crate::pe_loader::Win32Teb> {
    unsafe { crate::pe_loader::current_teb() }
}

fn current_win32_peb() -> Option<&'static mut crate::pe_loader::Win32Peb> {
    unsafe { crate::pe_loader::current_peb() }
}

fn current_win32_owner_key() -> u64 {
    if let Some(launch) = WIN32_THREAD_LAUNCHES
        .lock()
        .get(&(crate::task::scheduler::current_task_id() as u64))
        .copied()
    {
        if launch.owner_pid != 0 {
            return launch.owner_pid;
        }
    }
    current_win32_process_key()
}

fn process_handle_count(owner: u64) -> usize {
    let file_count = FILE_HANDLES
        .lock()
        .values()
        .filter(|state| state.owner_process == owner)
        .count();
    let internet_count = INTERNET_HANDLE_OWNERS
        .lock()
        .values()
        .filter(|&&pid| pid == owner)
        .count();
    file_count + internet_count
}

fn can_allocate_process_handle(owner: u64) -> bool {
    process_handle_count(owner) < MAX_HANDLES_PER_PROCESS
}

fn try_reserve_process_allocation(owner: u64, bytes: usize) -> bool {
    let mut usage = ALLOC_USAGE_PER_PROCESS.lock();
    let current = usage.get(&owner).copied().unwrap_or(0);
    let Some(next) = current.checked_add(bytes) else {
        return false;
    };
    if next > MAX_WIN32_ALLOC_BYTES_PER_PROCESS {
        return false;
    }
    usage.insert(owner, next);
    true
}

fn release_process_allocation(owner: u64, bytes: usize) {
    let mut usage = ALLOC_USAGE_PER_PROCESS.lock();
    let current = usage.get(&owner).copied().unwrap_or(0);
    let remaining = current.saturating_sub(bytes);
    if remaining == 0 {
        usage.remove(&owner);
    } else {
        usage.insert(owner, remaining);
    }
}

fn win32_last_error() -> DWORD {
    if let Some(teb) = current_win32_teb() {
        return teb.last_error_value;
    }
    THREAD_LAST_ERROR
        .lock()
        .get(&current_win32_thread_key())
        .copied()
        .unwrap_or(0)
}

fn set_win32_last_error(code: DWORD) {
    if let Some(teb) = current_win32_teb() {
        teb.last_error_value = code;
        return;
    }
    THREAD_LAST_ERROR
        .lock()
        .insert(current_win32_thread_key(), code);
}

fn map_http_error_to_internet_error(err: crate::net::http::HttpError) -> DWORD {
    use crate::net::http::HttpError;

    match err {
        HttpError::Timeout => ERROR_INTERNET_TIMEOUT,
        HttpError::ProxyAuthenticationRequired => ERROR_INTERNET_LOGIN_FAILURE,
        HttpError::ConnectionFailed => ERROR_INTERNET_CANNOT_CONNECT,
        HttpError::TlsCertDateInvalid => ERROR_INTERNET_SEC_CERT_DATE_INVALID,
        HttpError::TlsCertCnInvalid => ERROR_INTERNET_SEC_CERT_CN_INVALID,
        HttpError::TlsInvalidCa => ERROR_INTERNET_INVALID_CA,
        HttpError::TlsCertRevoked => ERROR_INTERNET_SEC_CERT_REVOKED,
        HttpError::TlsDecodeFailed => ERROR_INTERNET_DECODING_FAILED,
        HttpError::TlsInvalidCertificate => ERROR_INTERNET_SEC_INVALID_CERT,
        HttpError::TlsHandshakeFailed => ERROR_INTERNET_SEC_CERT_ERRORS,
        _ => ERROR_INTERNET_CANNOT_CONNECT,
    }
}

unsafe fn read_ansi_string(ptr: LPCSTR) -> String {
    if ptr.is_null() {
        return String::new();
    }
    let mut out = String::new();
    let mut cursor = ptr;
    while *cursor != 0 {
        out.push(*cursor as u8 as char);
        cursor = cursor.add(1);
    }
    out
}

unsafe fn read_ansi_string_counted(ptr: LPCSTR, count: INT) -> String {
    if ptr.is_null() || count == 0 {
        return String::new();
    }
    if count < 0 {
        return read_ansi_string(ptr);
    }
    let mut out = String::new();
    let mut cursor = ptr;
    for _ in 0..count {
        if *cursor == 0 {
            break;
        }
        out.push(*cursor as u8 as char);
        cursor = cursor.add(1);
    }
    out
}

fn text_metrics_for_dc(dc: &Win32DC) -> (INT, INT) {
    let height = dc.font_height.abs().max(8);
    let width = (height / 2).max(1);
    (width, height)
}

fn pack_text_extent(width: INT, height: INT) -> DWORD {
    ((height.max(0) as u32 & 0xFFFF) << 16) | (width.max(0) as u32 & 0xFFFF)
}

fn string_pixel_width(text: &str, char_width: INT) -> INT {
    (text.chars().count() as INT).saturating_mul(char_width.max(1))
}

fn wrap_text_lines(text: &str, max_chars: usize, single_line: bool) -> Vec<String> {
    if single_line || max_chars == 0 {
        return vec![text.replace('\n', " ")];
    }
    let mut lines = Vec::new();
    for raw_line in text.split('\n') {
        let mut current = String::new();
        for word in raw_line.split_whitespace() {
            let projected = if current.is_empty() {
                word.len()
            } else {
                current.len() + 1 + word.len()
            };
            if projected > max_chars && !current.is_empty() {
                lines.push(current.clone());
                current.clear();
            }
            if !current.is_empty() {
                current.push(' ');
            }
            if word.len() > max_chars && max_chars > 0 {
                let mut chars = word.chars().peekable();
                while chars.peek().is_some() {
                    if current.len() == max_chars {
                        lines.push(current.clone());
                        current.clear();
                    }
                    while current.len() < max_chars {
                        let Some(ch) = chars.next() else {
                            break;
                        };
                        current.push(ch);
                    }
                    if chars.peek().is_some() && !current.is_empty() {
                        lines.push(current.clone());
                        current.clear();
                    }
                }
            } else {
                current.push_str(word);
            }
        }
        lines.push(current);
    }
    if lines.is_empty() {
        lines.push(String::new());
    }
    lines
}

fn expand_tabs_to_columns(
    text: &str,
    tab_positions: &[INT],
    tab_origin: INT,
    char_width: INT,
) -> String {
    let mut out = String::new();
    let mut cursor_px = tab_origin.max(0);
    let width = char_width.max(1);
    for ch in text.chars() {
        if ch == '\t' {
            let default_step = width * 8;
            let next_stop = tab_positions
                .iter()
                .copied()
                .filter(|stop| *stop > cursor_px)
                .min()
                .unwrap_or_else(|| {
                    let base = if cursor_px <= tab_origin {
                        tab_origin
                    } else {
                        cursor_px
                    };
                    let delta = base - tab_origin;
                    tab_origin + (((delta / default_step) + 1) * default_step)
                });
            let spaces = ((next_stop - cursor_px) / width).max(1) as usize;
            for _ in 0..spaces {
                out.push(' ');
            }
            cursor_px = next_stop;
        } else {
            out.push(ch);
            cursor_px += width;
        }
    }
    out
}

fn draw_text_line_on_window(
    window: &mut Win32Window,
    clip_region: HRGN,
    mut x: INT,
    y: INT,
    text: &str,
    text_color: DWORD,
    bk_color: DWORD,
    bk_mode: INT,
    dx: Option<&[INT]>,
    clip_rect: Option<RECT>,
    char_width: INT,
    char_height: INT,
) -> RECT {
    let mut right = x;
    let left = x;
    let rect = clip_rect.map(normalize_rect);
    let r = ((text_color >> 16) & 0xFF) as u8;
    let g = ((text_color >> 8) & 0xFF) as u8;
    let b = (text_color & 0xFF) as u8;
    let br = ((bk_color >> 16) & 0xFF) as u8;
    let bg = ((bk_color >> 8) & 0xFF) as u8;
    let bb = (bk_color & 0xFF) as u8;

    for (index, ch) in text.chars().enumerate() {
        let advance = dx
            .and_then(|entries| entries.get(index).copied())
            .unwrap_or(char_width)
            .max(1);
        let glyph = crate::win32::gdi32::get_ascii_glyph(ch);
        for row in 0..char_height {
            let py = y + row;
            if py < 0 || py >= window.height {
                continue;
            }
            let bits = glyph[row as usize];
            for col in 0..advance {
                let px = x + col;
                if px < 0 || px >= window.width {
                    continue;
                }
                if clip_region != 0 && !region_contains_point(clip_region, px, py) {
                    continue;
                }
                if let Some(rect) = rect {
                    if px < rect.left || py < rect.top || px >= rect.right || py >= rect.bottom {
                        continue;
                    }
                }
                let idx = ((py as usize) * window.width as usize + px as usize) * 4;
                if idx + 3 >= window.surface.len() {
                    continue;
                }
                let glyph_on = col < char_width && (bits & (1 << (7 - col.min(7)))) != 0;
                if glyph_on {
                    window.surface[idx] = b;
                    window.surface[idx + 1] = g;
                    window.surface[idx + 2] = r;
                    window.surface[idx + 3] = 0xFF;
                } else if bk_mode == 2 {
                    window.surface[idx] = bb;
                    window.surface[idx + 1] = bg;
                    window.surface[idx + 2] = br;
                    window.surface[idx + 3] = 0xFF;
                }
            }
        }
        x += advance;
        right = x;
    }
    normalize_rect(RECT {
        left,
        top: y,
        right: right.max(left),
        bottom: y + char_height,
    })
}

fn fill_window_rect(window: &mut Win32Window, clip_region: HRGN, rect: RECT, color: DWORD) -> RECT {
    let rect = normalize_rect(rect);
    let r = ((color >> 16) & 0xFF) as u8;
    let g = ((color >> 8) & 0xFF) as u8;
    let b = (color & 0xFF) as u8;
    for y in rect.top.max(0)..rect.bottom.min(window.height) {
        for x in rect.left.max(0)..rect.right.min(window.width) {
            if clip_region != 0 && !region_contains_point(clip_region, x, y) {
                continue;
            }
            let idx = ((y as usize) * window.width as usize + x as usize) * 4;
            if idx + 3 >= window.surface.len() {
                continue;
            }
            window.surface[idx] = b;
            window.surface[idx + 1] = g;
            window.surface[idx + 2] = r;
            window.surface[idx + 3] = 0xFF;
        }
    }
    rect
}

