    /// EnumWindows
    pub unsafe fn enum_windows(
        lpEnumFunc: Option<unsafe extern "system" fn(HWND, usize) -> BOOL>,
        lParam: usize,
    ) -> BOOL {
        let Some(callback) = lpEnumFunc else {
            return FALSE;
        };
        let hwnds: Vec<u64> = crate::win32::WIN32_WINDOWS
            .lock()
            .values()
            .filter(|w| w.parent == 0)
            .map(|w| w.hwnd)
            .collect();
        for hwnd in hwnds {
            if callback(hwnd as HWND, lParam) == FALSE {
                return FALSE;
            }
        }
        TRUE
    }

