    /// MessageBoxA
    pub unsafe fn message_box_a(hWnd: HWND, lpText: LPCSTR, lpCaption: LPCSTR, uType: UINT) -> INT {
        let mut text = String::new();
        let mut ptr = lpText;
        while !ptr.is_null() && *ptr != 0 {
            text.push(*ptr as u8 as char);
            ptr = ptr.add(1);
        }
        crate::serial_println!("[WIN32] MessageBoxA: {}", text);
        1 // IDOK
    }

