    /// DialogBoxParamA
    pub unsafe fn dialog_box_param_a(
        hInstance: HINSTANCE,
        lpTemplateName: LPCSTR,
        hWndParent: HWND,
        lpDialogFunc: Option<unsafe extern "system" fn(HWND, UINT, usize, isize) -> isize>,
        dwInitParam: usize,
    ) -> isize {
        let dialog = create_dialog_param_a(
            hInstance,
            lpTemplateName,
            hWndParent,
            lpDialogFunc,
            dwInitParam,
        );
        if dialog == 0 {
            return -1;
        }
        if let Some(state) = crate::win32::WIN32_DIALOGS.lock().get_mut(&(dialog as u64)) {
            state.modal = true;
        }
        if show_window(dialog, SW_SHOW) == FALSE {
            return -1;
        }
        let mut msg = MSG {
            hwnd: 0,
            message: 0,
            wParam: 0,
            lParam: 0,
            time: 0,
            pt: POINT::default(),
        };
        loop {
            let ended = crate::win32::WIN32_DIALOGS
                .lock()
                .get(&(dialog as u64))
                .map(|state| state.ended)
                .unwrap_or(true);
            if ended {
                break;
            }
            if get_message_a(&mut msg, 0, 0, 0) == FALSE {
                break;
            }
            if is_dialog_message_a(dialog, &mut msg) == FALSE {
                let _ = translate_message(&msg);
                let _ = dispatch_message_a(&msg);
            }
        }
        crate::win32::WIN32_DIALOGS
            .lock()
            .remove(&(dialog as u64))
            .map(|state| state.result)
            .unwrap_or(-1)
    }

    pub unsafe fn dialog_box_indirect_param_a(
        hInstance: HINSTANCE,
        hDialogTemplate: *const crate::win32::DLGTEMPLATE,
        hWndParent: HWND,
        lpDialogFunc: Option<unsafe extern "system" fn(HWND, UINT, usize, isize) -> isize>,
        dwInitParam: isize,
    ) -> isize {
        let _ = hInstance;
        let dialog = create_dialog_from_template(
            hDialogTemplate,
            hWndParent,
            lpDialogFunc,
            dwInitParam as usize,
        );
        if dialog == 0 {
            return -1;
        }
        if let Some(state) = crate::win32::WIN32_DIALOGS.lock().get_mut(&(dialog as u64)) {
            state.modal = true;
        }
        let _ = show_window(dialog, SW_SHOW);
        let mut msg = MSG {
            hwnd: 0,
            message: 0,
            wParam: 0,
            lParam: 0,
            time: 0,
            pt: POINT::default(),
        };
        loop {
            let ended = crate::win32::WIN32_DIALOGS
                .lock()
                .get(&(dialog as u64))
                .map(|state| state.ended)
                .unwrap_or(true);
            if ended {
                break;
            }
            if get_message_a(&mut msg, 0, 0, 0) == FALSE {
                break;
            }
            if is_dialog_message_a(dialog, &mut msg) == FALSE {
                let _ = translate_message(&msg);
                let _ = dispatch_message_a(&msg);
            }
        }
        crate::win32::WIN32_DIALOGS
            .lock()
            .remove(&(dialog as u64))
            .map(|state| state.result)
            .unwrap_or(-1)
    }

    /// EndDialog
    pub unsafe fn end_dialog(hDlg: HWND, nResult: isize) -> BOOL {
        let mut dialogs = crate::win32::WIN32_DIALOGS.lock();
        let Some(state) = dialogs.get_mut(&(hDlg as u64)) else {
            return FALSE;
        };
        state.ended = true;
        state.result = nResult;
        let should_destroy = state.modal;
        drop(dialogs);
        if should_destroy {
            let _ = destroy_window(hDlg);
        } else {
            let _ = show_window(hDlg, crate::win32::SW_HIDE);
        }
        TRUE
    }

    /// CreateDialogParamA
    pub unsafe fn create_dialog_param_a(
        hInstance: HINSTANCE,
        lpTemplateName: LPCSTR,
        hWndParent: HWND,
        lpDialogFunc: Option<unsafe extern "system" fn(HWND, UINT, usize, isize) -> isize>,
        dwInitParam: usize,
    ) -> HWND {
        let hwnd = create_window_ex_a(
            0,
            b"#32770\0".as_ptr() as LPCSTR,
            lpTemplateName,
            WS_CAPTION | WS_SYSMENU | WS_VISIBLE,
            160,
            120,
            420,
            240,
            hWndParent,
            0,
            hInstance,
            core::ptr::null_mut(),
        );
        if hwnd == 0 {
            return 0;
        }
        crate::win32::WIN32_DIALOGS.lock().insert(
            hwnd as u64,
            crate::win32::Win32DialogState {
                hwnd,
                owner: hWndParent,
                modal: false,
                ended: false,
                result: 0,
                default_id: crate::win32::IDOK,
                focused_id: crate::win32::IDOK,
                is_extended: false,
            },
        );
        if let Some(proc_fn) = lpDialogFunc {
            let _ = proc_fn(
                hwnd,
                crate::win32::WM_INITDIALOG,
                hWndParent as usize,
                dwInitParam as isize,
            );
        }
        hwnd
    }

    pub unsafe fn create_dialog_indirect_param_a(
        hInstance: HINSTANCE,
        hDialogTemplate: *const crate::win32::DLGTEMPLATE,
        hWndParent: HWND,
        lpDialogFunc: Option<unsafe extern "system" fn(HWND, UINT, usize, isize) -> isize>,
        dwInitParam: isize,
    ) -> HWND {
        let _ = hInstance;
        create_dialog_from_template(
            hDialogTemplate,
            hWndParent,
            lpDialogFunc,
            dwInitParam as usize,
        )
    }

