    /// GetUserNameA
    pub unsafe fn get_user_name_a(lpBuffer: LPSTR, nSize: *mut DWORD) -> BOOL {
        if !lpBuffer.is_null() && !nSize.is_null() {
            let name = b"echOS\0";
            let size = *nSize as usize;
            if size >= name.len() {
                for (i, &c) in name.iter().enumerate() {
                    *lpBuffer.add(i) = c as i8;
                }
                *nSize = (name.len() - 1) as DWORD;
                return TRUE;
            }
        }
        FALSE
    }

