    /// ShellExecuteA
    pub unsafe fn shell_execute_a(
        hwnd: HWND,
        lpOperation: LPCSTR,
        lpFile: LPCSTR,
        lpParameters: LPCSTR,
        lpDirectory: LPCSTR,
        nShowCmd: INT,
    ) -> HINSTANCE {
        let mut file = String::new();
        let mut ptr = lpFile;
        while !ptr.is_null() && *ptr != 0 {
            file.push(*ptr as u8 as char);
            ptr = ptr.add(1);
        }
        crate::serial_println!("[WIN32] ShellExecuteA: {}", file);
        1 as HINSTANCE
    }

