    pub unsafe fn create_pen_indirect(lplgpn: *const u8) -> HPEN {
        if lplgpn.is_null() {
            return 0;
        }
        let style = *(lplgpn as *const INT);
        let width = *(lplgpn.add(4) as *const INT);
        let color = *(lplgpn.add(12) as *const DWORD);
        create_pen(style, width, color)
    }

