    /// SetTextColor
    pub unsafe fn set_text_color(hdc: HDC, crColor: DWORD) -> DWORD {
        let mut dcs = crate::win32::WIN32_DCS.lock();
        let Some(dc) = dcs.get_mut(&(hdc as u64)) else {
            return 0xFFFF_FFFF;
        };
        let previous = dc.text_color;
        dc.text_color = crColor & 0x00FF_FFFF;
        previous
    }

