    #[test]
    fn gdi_modes_and_path_fill_are_stateful() {
        unsafe {
            init();
            let hwnd = user32::create_window_ex_a(
                0,
                b"Phase2Window\0".as_ptr() as LPCSTR,
                b"gdi\0".as_ptr() as LPCSTR,
                WS_OVERLAPPEDWINDOW,
                0,
                0,
                80,
                80,
                0,
                0,
                0,
                core::ptr::null_mut(),
            );
            let hdc = user32::get_dc(hwnd);
            assert_ne!(hdc, 0);
            assert_eq!(gdi32::set_graphics_mode(hdc, 2), 1);
            assert_eq!(gdi32::set_arc_direction(hdc, 2), 1);
            assert_eq!(gdi32::set_poly_fill_mode(hdc, 2), 1);
            assert_eq!(gdi32::set_stretch_blt_mode(hdc, 4), 1);
            assert_eq!(gdi32::get_graphics_mode(hdc), 2);
            assert_eq!(gdi32::get_arc_direction(hdc), 2);
            assert_eq!(gdi32::get_poly_fill_mode(hdc), 2);
            assert_eq!(gdi32::get_stretch_blt_mode(hdc), 4);

            assert_eq!(gdi32::begin_path(hdc), TRUE);
            assert_eq!(gdi32::move_to_ex(hdc, 10, 10, core::ptr::null_mut()), TRUE);
            assert_eq!(gdi32::line_to(hdc, 40, 10), TRUE);
            assert_eq!(gdi32::line_to(hdc, 25, 40), TRUE);
            assert_eq!(gdi32::close_figure(hdc), TRUE);
            assert_eq!(gdi32::end_path(hdc), TRUE);
            let region = gdi32::path_to_region(hdc);
            assert_ne!(region, 0);
            let regions = WIN32_REGIONS.lock();
            let state = regions.get(&(region as u64)).unwrap();
            assert!(
                matches!(
                    &state.shape,
                    Win32RegionShape::Polygon {
                        alternate_fill: false,
                        ..
                    }
                ),
                "expected polygon region"
            );
            drop(regions);
            assert_eq!(gdi32::delete_object(region as HGDIOBJ), TRUE);
        }
    }

    #[test]
    fn gdi_blits_invalidate_destination_rects() {
        unsafe {
            init();
            INVALIDATED_WINDOWS.lock().clear();
            let src = user32::create_window_ex_a(
                0,
                b"Phase2Window\0".as_ptr() as LPCSTR,
                b"src\0".as_ptr() as LPCSTR,
                WS_OVERLAPPEDWINDOW,
                0,
                0,
                32,
                32,
                0,
                0,
                0,
                core::ptr::null_mut(),
            );
            let dst = user32::create_window_ex_a(
                0,
                b"Phase2Window\0".as_ptr() as LPCSTR,
                b"dst\0".as_ptr() as LPCSTR,
                WS_OVERLAPPEDWINDOW,
                0,
                0,
                32,
                32,
                0,
                0,
                0,
                core::ptr::null_mut(),
            );
            let src_dc = user32::get_dc(src);
            let dst_dc = user32::get_dc(dst);
            assert_eq!(
                gdi32::bit_blt(dst_dc, 2, 3, 4, 5, src_dc, 0, 0, 0x00CC0020),
                TRUE
            );
            assert_eq!(
                gdi32::stretch_blt(dst_dc, 6, 7, 8, 9, src_dc, 0, 0, 4, 4, 0x00CC0020),
                TRUE
            );
            let invalid = INVALIDATED_WINDOWS.lock();
            assert_eq!(
                invalid.get(&(dst as u64)).copied(),
                Some(RECT {
                    left: 2,
                    top: 3,
                    right: 14,
                    bottom: 16,
                })
            );
        }
    }

    #[test]
    fn user32_window_properties_are_stateful() {
        unsafe extern "system" fn enum_proc(hwnd: HWND, name: LPCSTR, value: HANDLE) -> BOOL {
            let key = read_ansi_string(name);
            if hwnd != 0 && (key == "alpha" || key == "beta") && value != 0 {
                TRUE
            } else {
                FALSE
            }
        }

        unsafe {
            init();
            let hwnd = user32::create_window_ex_a(
                0,
                b"Phase2Window\0".as_ptr() as LPCSTR,
                b"props\0".as_ptr() as LPCSTR,
                WS_OVERLAPPEDWINDOW,
                0,
                0,
                40,
                40,
                0,
                0,
                0,
                core::ptr::null_mut(),
            );
            assert_ne!(hwnd, 0);
            assert_eq!(
                user32::set_prop_a(hwnd, b"alpha\0".as_ptr() as LPCSTR, 0x11 as HANDLE),
                TRUE
            );
            assert_eq!(
                user32::set_prop_a(hwnd, b"beta\0".as_ptr() as LPCSTR, 0x22 as HANDLE),
                TRUE
            );
            assert_eq!(
                user32::get_prop_a(hwnd, b"alpha\0".as_ptr() as LPCSTR),
                0x11 as HANDLE
            );
            assert_eq!(user32::enum_props_a(hwnd, Some(enum_proc)), 2);
            assert_eq!(
                user32::remove_prop_a(hwnd, b"alpha\0".as_ptr() as LPCSTR),
                0x11 as HANDLE
            );
            assert_eq!(user32::get_prop_a(hwnd, b"alpha\0".as_ptr() as LPCSTR), 0);
            assert_eq!(user32::enum_props_a(hwnd, Some(enum_proc)), 1);
        }
    }

    #[test]
    fn gdi_text_draw_and_extent_paths_are_stateful() {
        unsafe {
            init();
            INVALIDATED_WINDOWS.lock().clear();
            let hwnd = user32::create_window_ex_a(
                0,
                b"Phase2Window\0".as_ptr() as LPCSTR,
                b"text\0".as_ptr() as LPCSTR,
                WS_OVERLAPPEDWINDOW,
                0,
                0,
                96,
                64,
                0,
                0,
                0,
                core::ptr::null_mut(),
            );
            let hdc = user32::get_dc(hwnd);
            assert_ne!(hdc, 0);
            assert_eq!(gdi32::set_text_color(hdc, 0x0000FF), 0x000000);
            assert_eq!(gdi32::set_bk_color(hdc, 0x00FF00), 0x00FFFFFF);
            assert_eq!(gdi32::set_bk_mode(hdc, 2), 2);

            let opaque = RECT {
                left: 2,
                top: 2,
                right: 34,
                bottom: 18,
            };
            assert_eq!(
                gdi32::ext_text_out_a(
                    hdc,
                    2,
                    2,
                    0x0002 | 0x0004,
                    &opaque,
                    b"Hi\0".as_ptr() as LPCSTR,
                    2,
                    core::ptr::null(),
                ),
                TRUE
            );

            let mut calc = RECT {
                left: 0,
                top: 0,
                right: 32,
                bottom: 32,
            };
            assert_eq!(
                gdi32::draw_text_a(
                    hdc,
                    b"A B C D\0".as_ptr() as LPCSTR,
                    -1,
                    &mut calc,
                    0x0010 | 0x0400,
                ),
                32
            );
            assert!(calc.right > calc.left);
            assert!(calc.bottom > calc.top);

            let tabs = [32, 64];
            let packed = gdi32::get_tabbed_text_extent_a(
                hdc,
                b"A\tB\0".as_ptr() as LPCSTR,
                3,
                tabs.len() as INT,
                tabs.as_ptr(),
            );
            assert!(packed != 0);
            assert_eq!(
                gdi32::tabbed_text_out_a(
                    hdc,
                    4,
                    20,
                    b"A\tB\0".as_ptr() as LPCSTR,
                    3,
                    tabs.len() as INT,
                    tabs.as_ptr(),
                    0,
                ),
                packed as LONG
            );

            let windows = WIN32_WINDOWS.lock();
            let win = windows.get(&(hwnd as u64)).unwrap();
            let idx = ((2usize) * win.width as usize + 2usize) * 4;
            assert_eq!(win.surface[idx], 0x00);
            assert_eq!(win.surface[idx + 1], 0xFF);
            assert_eq!(win.surface[idx + 2], 0x00);
            drop(windows);

            let invalid = INVALIDATED_WINDOWS.lock();
            assert!(invalid.get(&(hwnd as u64)).is_some());
        }
    }

