    #[test]
    fn msvcrt_streams_and_numeric_helpers_are_stateful() {
        unsafe {
            init();
            let path = b"/phase2_exact_stdio.txt\0";
            let mode = b"w+\0";
            let stream = msvcrt::fopen(path.as_ptr() as LPCSTR, mode.as_ptr() as LPCSTR);
            assert!(!stream.is_null());

            let payload = b"phase2-data";
            assert_eq!(
                msvcrt::fwrite(payload.as_ptr(), 1, payload.len() as SIZE_T, stream),
                payload.len() as SIZE_T
            );
            assert_eq!(msvcrt::fseek(stream, 0, 0), 0);

            let mut read_back = [0u8; 16];
            assert_eq!(
                msvcrt::fread(read_back.as_mut_ptr(), 1, payload.len() as SIZE_T, stream),
                payload.len() as SIZE_T
            );
            assert_eq!(&read_back[..payload.len()], payload);
            assert_eq!(msvcrt::ftell(stream), payload.len() as LONG);
            assert_eq!(msvcrt::fclose(stream), 0);

            let mut sprintf_buf = [0i8; 64];
            let args = [0x2Au64, b"ok\0".as_ptr() as u64];
            assert_eq!(
                msvcrt::sprintf(
                    sprintf_buf.as_mut_ptr(),
                    b"value=%d %s\0".as_ptr() as LPCSTR,
                    args.as_ptr() as *const u8,
                ),
                11
            );
            assert_eq!(read_ansi_string(sprintf_buf.as_ptr()), "value=42 ok");

            let mut end = core::ptr::null_mut();
            assert_eq!(
                msvcrt::strtol(b"0x2a rest\0".as_ptr() as LPCSTR, &mut end, 0),
                42
            );
            assert_eq!(read_ansi_string(end as LPCSTR), " rest");
            assert!(
                (msvcrt::strtod(b"12.5e1x\0".as_ptr() as LPCSTR, &mut end) - 125.0).abs() < 0.01
            );
            assert_eq!(read_ansi_string(end as LPCSTR), "x");

            let now = msvcrt::time(core::ptr::null_mut());
            assert!(now >= 0);
            let tm_ptr = msvcrt::gmtime(&now);
            assert!(!tm_ptr.is_null());
            let mut strftime_buf = [0i8; 64];
            assert!(
                msvcrt::strftime(
                    strftime_buf.as_mut_ptr(),
                    strftime_buf.len() as SIZE_T,
                    b"%Y-%m-%d %H:%M:%S\0".as_ptr() as LPCSTR,
                    tm_ptr,
                ) > 0
            );
        }
    }

    #[test]
    fn msvcrt_scanf_locale_system_and_exit_are_stateful() {
        static EXIT_TRACE: core::sync::atomic::AtomicUsize =
            core::sync::atomic::AtomicUsize::new(0);

        extern "C" fn on_exit_first() {
            let prior = EXIT_TRACE.load(core::sync::atomic::Ordering::Relaxed);
            EXIT_TRACE.store(prior * 10 + 1, core::sync::atomic::Ordering::Relaxed);
        }

        extern "C" fn on_exit_second() {
            let prior = EXIT_TRACE.load(core::sync::atomic::Ordering::Relaxed);
            EXIT_TRACE.store(prior * 10 + 2, core::sync::atomic::Ordering::Relaxed);
        }

        unsafe {
            init();
            set_test_stdin("42 3.5 sample Z");

            let mut scanned_int = 0i32;
            let mut scanned_float = 0f32;
            let mut scanned_word = [0i8; 32];
            let mut scanned_char = 0i8;
            let args = [
                (&mut scanned_int as *mut i32) as usize as u64,
                (&mut scanned_float as *mut f32) as usize as u64,
                scanned_word.as_mut_ptr() as usize as u64,
                (&mut scanned_char as *mut i8) as usize as u64,
            ];
            assert_eq!(
                msvcrt::scanf(
                    b"%d %f %s %c\0".as_ptr() as LPCSTR,
                    args.as_ptr() as *const u8,
                ),
                4
            );
            assert_eq!(scanned_int, 42);
            assert!((scanned_float - 3.5).abs() < 0.01);
            assert_eq!(read_ansi_string(scanned_word.as_ptr()), "sample");
            assert_eq!(scanned_char, b'Z' as i8);

            let locale = msvcrt::setlocale(0, b"en-US\0".as_ptr() as LPCSTR);
            assert_eq!(read_ansi_string(locale), "en-US");
            let locale = msvcrt::setlocale(5, core::ptr::null());
            assert_eq!(read_ansi_string(locale), "en-US");
            let locale = msvcrt::setlocale(4, b"C\0".as_ptr() as LPCSTR);
            assert_eq!(read_ansi_string(locale), "C");
            let locale = msvcrt::setlocale(4, core::ptr::null());
            assert_eq!(read_ansi_string(locale), "C");

            assert_eq!(msvcrt::system(core::ptr::null()), 1);
            assert_eq!(msvcrt::system(b"echo phase2-crt\0".as_ptr() as LPCSTR), 0);
            assert_eq!(
                msvcrt::system(b"faz2_olmayan_komut\0".as_ptr() as LPCSTR),
                127
            );

            EXIT_TRACE.store(0, core::sync::atomic::Ordering::Relaxed);
            assert_eq!(msvcrt::atexit(Some(on_exit_first)), 0);
            assert!(msvcrt::_onexit(Some(on_exit_second)).is_some());
            msvcrt::exit(23);
            assert_eq!(*crt_exit_status_state().lock(), Some(23));
            assert_eq!(EXIT_TRACE.load(core::sync::atomic::Ordering::Relaxed), 21);
        }
    }

    #[test]
    fn msvcrt_abi_exotica_env_locale_and_stdio_edges_are_stateful() {
        unsafe {
            init();

            let path = b"/phase4_crt_stdio.txt\0";
            let renamed = b"/phase4_crt_stdio_renamed.txt\0";
            let stream = msvcrt::fopen(path.as_ptr() as LPCSTR, b"w+\0".as_ptr() as LPCSTR);
            assert!(!stream.is_null());
            assert_eq!(msvcrt::fwrite(b"abc".as_ptr(), 1, 3, stream), 3);
            assert_eq!(msvcrt::fflush(stream), 0);
            assert_eq!(msvcrt::fseek(stream, 0, 0), 0);

            let mut byte = [0u8; 1];
            assert_eq!(msvcrt::fread(byte.as_mut_ptr(), 1, 1, stream), 1);
            assert_eq!(msvcrt::fread(byte.as_mut_ptr(), 1, 1, stream), 1);
            assert_eq!(msvcrt::fread(byte.as_mut_ptr(), 1, 1, stream), 1);
            assert_eq!(msvcrt::fread(byte.as_mut_ptr(), 1, 1, stream), 0);
            assert_eq!(msvcrt::feof(stream), 1);
            assert_eq!(msvcrt::ferror(stream), 0);

            msvcrt::clearerr(stream);
            assert_eq!(msvcrt::feof(stream), 0);
            msvcrt::rewind(stream);
            assert_eq!(msvcrt::ftell(stream), 0);
            assert_eq!(msvcrt::fclose(stream), 0);

            assert_eq!(
                msvcrt::rename(path.as_ptr() as LPCSTR, renamed.as_ptr() as LPCSTR),
                0
            );
            assert!(crt_host_files_state()
                .lock()
                .contains_key("/phase4_crt_stdio_renamed.txt"));
            assert_eq!(msvcrt::remove(renamed.as_ptr() as LPCSTR), 0);
            assert!(!crt_host_files_state()
                .lock()
                .contains_key("/phase4_crt_stdio_renamed.txt"));

            assert_eq!(
                msvcrt::_putenv(b"PHASE4_EDGE=enabled\0".as_ptr() as LPCSTR),
                0
            );
            assert_eq!(
                read_ansi_string(msvcrt::getenv(b"PHASE4_EDGE\0".as_ptr() as LPCSTR)),
                "enabled"
            );

            let mut dup = core::ptr::null_mut();
            let mut count: SIZE_T = 0;
            assert_eq!(
                msvcrt::_dupenv_s(&mut dup, &mut count, b"PHASE4_EDGE\0".as_ptr() as LPCSTR,),
                0
            );
            assert_eq!(count, 8);
            assert_eq!(read_ansi_string(dup), "enabled");
            win32_dealloc(dup as *mut u8);

            let mut full = [0i8; 128];
            let full_ptr = msvcrt::_fullpath(
                full.as_mut_ptr(),
                b".\\phase4\\edge.txt\0".as_ptr() as LPCSTR,
                full.len() as SIZE_T,
            );
            assert_eq!(full_ptr, full.as_mut_ptr());
            assert_eq!(read_ansi_string(full.as_ptr()), "C:\\phase4\\edge.txt");

            let mut drive = [0i8; 8];
            let mut dir = [0i8; 64];
            let mut fname = [0i8; 32];
            let mut ext = [0i8; 16];
            msvcrt::_splitpath(
                full.as_ptr() as LPCSTR,
                drive.as_mut_ptr(),
                dir.as_mut_ptr(),
                fname.as_mut_ptr(),
                ext.as_mut_ptr(),
            );
            assert_eq!(read_ansi_string(drive.as_ptr()), "C:");
            assert_eq!(read_ansi_string(dir.as_ptr()), "\\phase4\\");
            assert_eq!(read_ansi_string(fname.as_ptr()), "edge");
            assert_eq!(read_ansi_string(ext.as_ptr()), ".txt");

            let mut rebuilt = [0i8; 128];
            msvcrt::_makepath(
                rebuilt.as_mut_ptr(),
                drive.as_ptr() as LPCSTR,
                dir.as_ptr() as LPCSTR,
                fname.as_ptr() as LPCSTR,
                ext.as_ptr() as LPCSTR,
            );
            assert_eq!(read_ansi_string(rebuilt.as_ptr()), "C:\\phase4\\edge.txt");

            let locale = msvcrt::setlocale(4, b"en-US\0".as_ptr() as LPCSTR);
            assert_eq!(read_ansi_string(locale), "en-US");
            let locale = msvcrt::setlocale(3, b"en-US\0".as_ptr() as LPCSTR);
            assert_eq!(read_ansi_string(locale), "en-US");
            let conv = msvcrt::localeconv();
            assert!(!conv.is_null());
            assert_eq!(read_ansi_string((*conv).decimal_point), ".");
            assert_eq!(read_ansi_string((*conv).thousands_sep), ",");
            assert_eq!(read_ansi_string((*conv).currency_symbol), "$");
            assert_eq!(read_ansi_string((*conv).int_curr_symbol), "USD ");
            assert_eq!(read_ansi_string((*conv).negative_sign), "-");
        }
    }

    #[test]
    fn process_handle_limit_is_enforced_for_file_handles() {
        unsafe {
            init();

            let owner = current_win32_owner_key();
            {
                let mut handles = FILE_HANDLES.lock();
                for i in 0..(MAX_HANDLES_PER_PROCESS - 1) {
                    handles.insert(
                        0x9000_0000 + i as u64,
                        Win32FileState {
                            fd: WIN32_HOST_FILE_FD,
                            path: alloc::format!("/prefilled_handle_{i}"),
                            access: GENERIC_READ,
                            is_console: false,
                            owner_process: owner,
                        },
                    );
                }
            }

            let allowed = kernel32::create_file_a(
                b"/handle_limit_allowed.txt\0".as_ptr() as LPCSTR,
                GENERIC_WRITE,
                0,
                core::ptr::null_mut(),
                CREATE_ALWAYS,
                0,
                0,
            );
            assert_ne!(allowed, INVALID_HANDLE_VALUE);

            let overflow = kernel32::create_file_a(
                b"/handle_limit_overflow.txt\0".as_ptr() as LPCSTR,
                GENERIC_WRITE,
                0,
                core::ptr::null_mut(),
                CREATE_ALWAYS,
                0,
                0,
            );
            assert_eq!(overflow, INVALID_HANDLE_VALUE);
            assert_eq!(win32_last_error(), ERROR_TOO_MANY_OPEN_FILES);
        }
    }

